import React, { useEffect, useState } from "react";
import { Route, Navigate } from "react-router-dom";
import { auth } from "./firebase"; // Import Firebase auth

const ProtectedRoute = ({ element: Element, ...rest }) => {
  const [loading, setLoading] = useState(true);
  const [isAuthenticated, setIsAuthenticated] = useState(false);

  useEffect(() => {
    const unsubscribe = auth.onAuthStateChanged(user => {
      setIsAuthenticated(!!user); // If a user exists, they're authenticated
      setLoading(false);
    });

    return () => unsubscribe();
  }, []);

  if (loading) {
    return <div>Loading...</div>; // Optionally, show a loading screen while checking authentication
  }

  return (
    <Route
      {...rest}
      element={isAuthenticated ? <Element /> : <Navigate to="/auth/login" />}
    />
  );
};

export default ProtectedRoute;
